import pytest

from bedrock_protocol import v1001, v2168

VERSIONS = {"v1001": v1001, "v2168": v2168}

# generated by gophertunnel b8bd735:
# &packet.PlayerEnchantOptions{Options: []protocol.EnchantmentOption{{Cost: 200,
# Enchantments: protocol.ItemEnchantments{Slot: 2, Enchantments: [3][]protocol.EnchantmentInstance{{{Type: 9, Level: 5},
# {Type: 36, Level: 1}}, {}, {{Type: 43, Level: 255}}}}, Name: "animal imbue range", RecipeNetworkID: 300},
# {Cost: 0, Enchantments: protocol.ItemEnchantments{Slot: -1}, Name: "z", RecipeNetworkID: 1}}}
OPTIONS = bytes.fromhex(
    "02c802000000020905240100012bff12616e696d616c20696d6275652072616e6765ac0200ffffffff000000017a01"
)

# generated by gophertunnel b8bd735:
# &packet.PlayerEnchantOptions{}
EMPTY = bytes.fromhex("00")

# generated by gophertunnel b8bd735:
# &packet.PlayerEnchantOptions{Options: []protocol.EnchantmentOption{{Cost: 200,
# Enchantments: protocol.ItemEnchantments{Slot: -1}}}}
COST_AND_SLOT = bytes.fromhex("01c8ffffffff0000000000")

GOLDENS = (
    [
        pytest.param(
            version.PlayerEnchantOptionsPacket(
                options=[
                    version.ItemEnchantOption(
                        cost=200,
                        enchants=version.ItemEnchants(
                            slot=2,
                            item_enchants=[
                                [
                                    version.EnchantmentInstance(enchant_type=version.Enchant.Type.SHARPNESS, level=5),
                                    version.EnchantmentInstance(enchant_type=version.Enchant.Type.SOUL_SPEED, level=1),
                                ],
                                [],
                                [
                                    version.EnchantmentInstance(
                                        enchant_type=version.Enchant.Type.INVALID_ENCHANTMENT, level=255
                                    )
                                ],
                            ],
                        ),
                        enchant_name="animal imbue range",
                        enchant_net_id=version.RecipeNetId(raw_id=300),
                    ),
                    version.ItemEnchantOption(
                        cost=0,
                        enchants=version.ItemEnchants(slot=-1, item_enchants=[[], [], []]),
                        enchant_name="z",
                        enchant_net_id=version.RecipeNetId(raw_id=1),
                    ),
                ]
            ),
            OPTIONS,
            id=f"{name}-two-options",
        )
        for name, version in VERSIONS.items()
    ]
    + [
        pytest.param(version.PlayerEnchantOptionsPacket(options=[]), EMPTY, id=f"{name}-empty")
        for name, version in VERSIONS.items()
    ]
    + [
        pytest.param(
            version.PlayerEnchantOptionsPacket(
                options=[
                    version.ItemEnchantOption(
                        cost=200,
                        enchants=version.ItemEnchants(slot=-1, item_enchants=[[], [], []]),
                        enchant_name="",
                        enchant_net_id=version.RecipeNetId(raw_id=0),
                    )
                ]
            ),
            COST_AND_SLOT,
            id=f"{name}-cost-and-slot",
        )
        for name, version in VERSIONS.items()
    ]
)


@pytest.mark.parametrize("version", VERSIONS.values(), ids=VERSIONS.keys())
def test_player_enchant_options_is_packet_146(version):
    assert version.PACKETS[146] is version.PlayerEnchantOptionsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_enchant_options_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_enchant_options_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
